suppressPackageStartupMessages({library(Seurat);library(Matrix);library(harmony);library(jsonlite);library(ggplot2)})
root<-Sys.getenv('PROJECT_ROOT');stopifnot(nchar(root)>0)
r<-file.path(root,'annotation_rebuild/20261105_v7_literature_guided_reannotation_v1');out<-file.path(r,'stage_h_mast_source_robust_refit_v1/refit')
stopifnot(!dir.exists(out));dir.create(out)
started<-format(Sys.time(),tz='UTC',usetz=TRUE);set.seed(20261105)
write_json(list(status='running',UTC_start=started,scope='Mast conservative QC sensitivity pool; not a final cell exclusion'),file.path(out,'started.json'),pretty=TRUE)
meta<-read.delim(gzfile(file.path(r,'stage_h_mast_source_robust_refit_v1/mast_allcell_metadata_PRIVATE.tsv.gz')),row.names=1,check.names=FALSE,stringsAsFactors=FALSE)
fit<-meta$Mast_source_robust_refit_candidate_v2 %in% c(TRUE,'True','TRUE','true',1,'1')
obj<-readRDS(file.path(r,'stage_c2_mast_initial_diagnostic/mast_initial_seurat_PRIVATE.rds'))
stopifnot(identical(colnames(obj),rownames(meta)))
obj<-subset(obj,cells=rownames(meta)[fit]);stopifnot(ncol(obj)==sum(fit))
DefaultAssay(obj)<-'RNA'
gene_map<-read.delim(file.path(r,'stage_c2_mast_initial_diagnostic/feature_id_gene_symbol_map.tsv'),check.names=FALSE,stringsAsFactors=FALSE)
features<-read.delim(file.path(r,'stage_g_mast_marker_QC_v2/source_robust_model_genes.tsv'),stringsAsFactors=FALSE)$gene_symbol
features<-gene_map$feature_id[match(features,gene_map$gene_symbol)];stopifnot(!anyNA(features),!anyDuplicated(features))
features<-intersect(features,rownames(obj));stopifnot(length(features)>10000)
# Model feature restriction does not subset the RNA assay or change its full-library normalization.
obj[['HVG_source_robust']]<-CreateAssayObject(counts=GetAssayData(obj,assay='RNA',layer='counts')[features,,drop=FALSE])
obj<-FindVariableFeatures(obj,assay='HVG_source_robust',selection.method='vst',nfeatures=2000,verbose=FALSE)
hvg<-VariableFeatures(obj[['HVG_source_robust']]);VariableFeatures(obj[['RNA']])<-hvg
write.table(data.frame(feature_id=hvg,gene_symbol=gene_map$gene_symbol[match(hvg,gene_map$feature_id)]),file.path(out,'HVG_source_robust.tsv'),sep='\t',quote=FALSE,row.names=FALSE)
obj<-ScaleData(obj,assay='RNA',features=hvg,verbose=FALSE)
obj<-RunPCA(obj,assay='RNA',features=hvg,npcs=50,seed.use=20261105,verbose=FALSE)
obj<-FindNeighbors(obj,reduction='pca',dims=1:30,graph.name=c('raw_nn','raw_snn'),verbose=FALSE)
obj<-FindClusters(obj,graph.name='raw_snn',resolution=.4,random.seed=20261105,verbose=FALSE)
# GSE correction is a source sensitivity, not a claim to reproduce an unknown Technology covariate.
obj<-RunHarmony(obj,group.by.vars='gse_id',reduction.use='pca',dims.use=1:30,reduction.save='harmony_source',project.dim=FALSE,verbose=FALSE)
obj<-FindNeighbors(obj,reduction='harmony_source',dims=1:30,graph.name=c('source_nn','source_snn'),verbose=FALSE)
res<-c(.2,.4,.6,.8,1)
obj<-FindClusters(obj,graph.name='source_snn',resolution=res,random.seed=20261105,verbose=FALSE)
obj<-RunUMAP(obj,reduction='harmony_source',dims=1:30,reduction.name='umap_source',reduction.key='UMAPsource_',seed.use=20261105,verbose=FALSE)
md<-obj[[]];graph_cols<-grep('^(raw|source)_snn_res',colnames(md),value=TRUE)
summary<-do.call(rbind,lapply(graph_cols,function(col){tt<-table(md[[col]]);data.frame(graph=col,cluster=names(tt),n_cells=as.integer(tt))}))
write.table(summary,file.path(out,'cluster_resolution_counts.tsv'),sep='\t',quote=FALSE,row.names=FALSE)
source_summary<-do.call(rbind,lapply(graph_cols,function(col){tt<-table(md[[col]],md$gse_id);data.frame(graph=col,cluster=rownames(tt),n_cells=rowSums(tt),n_gse=rowSums(tt>0),max_gse_fraction=apply(tt,1,max)/rowSums(tt))}))
write.table(source_summary,file.path(out,'cluster_source_concentration.tsv'),sep='\t',quote=FALSE,row.names=FALSE)
Idents(obj)<-'source_snn_res.0.4';DefaultAssay(obj)<-'RNA'
markers<-FindAllMarkers(obj,assay='RNA',slot='data',min.pct=.1,min.diff.pct=.25,logfc.threshold=.25,return.thresh=.01,only.pos=FALSE,test.use='wilcox',verbose=FALSE)
markers$feature_id<-markers$gene;markers$gene<-gene_map$gene_symbol[match(markers$feature_id,gene_map$feature_id)];stopifnot(!anyNA(markers$gene))
write.table(markers,file.path(out,'RNA_FindAllMarkers_source_res0.4.tsv'),sep='\t',quote=FALSE,row.names=FALSE)
write.table(cbind(cell_id=rownames(md),md),gzfile(file.path(out,'metadata_PRIVATE.tsv.gz')),sep='\t',quote=FALSE,row.names=FALSE)
pdf(file.path(out,'refit_diagnostic.pdf'),width=14,height=8)
print(ElbowPlot(obj,ndims=50));print(DimPlot(obj,reduction='umap_source',group.by='source_snn_res.0.4',label=TRUE,raster=TRUE)+ggtitle('Mast source-robust model: exploratory clusters'))
print(DimPlot(obj,reduction='umap_source',group.by='gse_id',raster=TRUE)+NoLegend())
print(DimPlot(obj,reduction='umap_source',group.by='final_annotation_v7',raster=TRUE))
print(FeaturePlot(obj,reduction='umap_source',features=c('TPSAB1','CPA3','CMA1','IL17RB','CD3D','CSF1R','MKI67','TOP2A'),ncol=4,raster=TRUE))
dev.off()
saveRDS(obj,file.path(out,'mast_source_robust_seurat_PRIVATE.rds'),compress=FALSE)
write_json(list(status='completed_source_robust_QC_sensitivity_refit',UTC_start=started,UTC_end=format(Sys.time(),tz='UTC',usetz=TRUE),n_cells=ncol(obj),n_RNA_features=nrow(obj[['RNA']]),n_model_feature_candidates=length(features),n_HVG=length(hvg),n_PCA=50,graph_PCs=30,source_covariate='gse_id; explicit source sensitivity, Technology unverified',resolutions=res,marker_resolution=.4,normalization='Original full-library RNA LogNormalize preserved',regressed_variables=character(),Seurat=as.character(packageVersion('Seurat')),Harmony=as.character(packageVersion('harmony')),new_final_annotation_changes=0),file.path(out,'complete.json'),auto_unbox=TRUE,pretty=TRUE)
